typedef struct x86_opcode_descriptor {
    cdisasm_x86_name_id name_id;
    uint8_t form;
    uint8_t argument;
    uint32_t groups;
} x86_opcode_descriptor;

_Static_assert(X86_DECODE_FORM_COUNT <= UINT8_MAX,
    "x86 decode forms must fit in x86_opcode_descriptor.form");

#define X86_OPCODE_DESCRIPTOR(name_, form_, argument_, groups_) { (name_), (uint8_t)(form_), (uint8_t)(argument_), (groups_) }

typedef enum x86_x87_form {
    X86_X87_FORM_INVALID = 0,
    X86_X87_FORM_MEMORY_READ = 1,
    X86_X87_FORM_MEMORY_WRITE = 2,
    X86_X87_FORM_ST0_STI_READ_WRITE = 3,
    X86_X87_FORM_STI_ST0_READ_WRITE = 4,
    X86_X87_FORM_ST0_STI_WRITE = 5,
    X86_X87_FORM_ST0_STI_READ = 6,
    X86_X87_FORM_STI_READ = 7,
    X86_X87_FORM_STI_WRITE = 8,
    X86_X87_FORM_STI_READ_WRITE = 9,
    X86_X87_FORM_AX_WRITE = 10,
    X86_X87_FORM_FIXED = 11,
    X86_X87_FORM_STI_ST0_WRITE = 12
} x86_x87_form;

typedef enum x86_x87_size {
    X86_X87_SIZE_NONE = 0,
    X86_X87_SIZE_16 = 16,
    X86_X87_SIZE_32 = 32,
    X86_X87_SIZE_64 = 64,
    X86_X87_SIZE_80 = 80,
    X86_X87_SIZE_ENV = 1,
    X86_X87_SIZE_STATE = 2
} x86_x87_size;

typedef enum x86_x87_feature {
    X86_X87_FEATURE_BASE = 0,
    X86_X87_FEATURE_287 = 1,
    X86_X87_FEATURE_387 = 2,
    X86_X87_FEATURE_P6 = 3,
    X86_X87_FEATURE_SSE3 = 4
} x86_x87_feature;

typedef struct x86_x87_descriptor {
    cdisasm_x86_name_id name_id;
    cdisasm_x86_name_id wait_name_id;
    uint8_t form;
    uint8_t size;
    uint8_t feature;
} x86_x87_descriptor;

typedef struct x86_x87_register_range {
    uint8_t opcode;
    uint8_t first_modrm;
    uint8_t last_modrm;
    x86_x87_descriptor descriptor;
} x86_x87_register_range;

#define X86_X87_DESCRIPTOR(name_, wait_name_, form_, size_, feature_) \
    { (name_), (wait_name_), (uint8_t)(form_), (uint8_t)(size_), (uint8_t)(feature_) }
#define X86_X87_MEMORY(name_, wait_name_, form_, size_, feature_) \
    X86_X87_DESCRIPTOR((name_), (wait_name_), (form_), (size_), (feature_))
#define X86_X87_RANGE(opcode_, first_, last_, name_, wait_name_, form_, feature_) \
    { (opcode_), (first_), (last_), \
        X86_X87_DESCRIPTOR((name_), (wait_name_), (form_), \
            X86_X87_SIZE_NONE, (feature_)) }

