/*
 * Legacy SIMD opcodes share byte values and are selected by the mandatory
 * 66/F2/F3 prefix.  Keeping those variants in separate per-map descriptor
 * tables avoids embedding mnemonic strings or CPU-policy decisions here.
 */
typedef enum x86_simd_prefix {
    X86_SIMD_PREFIX_NONE = 0,
    X86_SIMD_PREFIX_P66 = 1,
    X86_SIMD_PREFIX_PF3 = 2,
    X86_SIMD_PREFIX_PF2 = 3
} x86_simd_prefix;

/* CET shadow-stack stores occupy two otherwise collision-heavy 0F38 rows.
 * Prefix matching stays table-driven so 66/F3 F6 can continue to select
 * ADCX/ADOX independently of CET feature validation. */
typedef struct x86_cet_store_descriptor {
    cdisasm_x86_name_id name32;
    cdisasm_x86_name_id name64;
    uint8_t opcode;
    uint8_t prefix;
    uint8_t privileged;
} x86_cet_store_descriptor;

static const x86_cet_store_descriptor x86_0f38_cet_store_map[] = {
    {CDISASM_X86_NAME_WRSSD, CDISASM_X86_NAME_WRSSQ,
     0xf6, X86_SIMD_PREFIX_NONE, 0},
    {CDISASM_X86_NAME_WRUSSD, CDISASM_X86_NAME_WRUSSQ,
     0xf5, X86_SIMD_PREFIX_P66, 1}
};

typedef enum x86_simd_feature {
    X86_SIMD_FEATURE_SSE = 1,
    X86_SIMD_FEATURE_SSE2 = 2,
    X86_SIMD_FEATURE_SSE3 = 3,
    X86_SIMD_FEATURE_SSSE3 = 4,
    X86_SIMD_FEATURE_SSE41 = 5,
    X86_SIMD_FEATURE_SSE4A = 6,
    X86_SIMD_FEATURE_SSE42 = 7,
    X86_SIMD_FEATURE_MMX = 8
} x86_simd_feature;

