/*
 * APX REX2 map-0 forms whose instruction layout is identical to the legacy
 * two-operand integer encoding.  Keep this structural table in both builds:
 * an extra-opcodes-OFF decoder still owns complete encodings (and therefore
 * their truncation/invalid-prefix errors) before reporting them unsupported.
 */
typedef enum x86_rex2_form {
    X86_REX2_FORM_RM_REG = 1,
    X86_REX2_FORM_REG_RM = 2
} x86_rex2_form;

typedef enum x86_rex2_flags {
    X86_REX2_FLAG_NONE = 0,
    X86_REX2_FLAG_BYTE = 1,
    X86_REX2_FLAG_LOCKABLE = 2
} x86_rex2_flags;

typedef struct x86_rex2_descriptor {
    cdisasm_x86_name_id name_id;
    uint8_t opcode;
    uint8_t form;
    uint8_t flags;
    uint8_t destination_access;
} x86_rex2_descriptor;

#define X86_REX2(name_, opcode_, form_, flags_, access_) \
    { (name_), (opcode_), (form_), (flags_), (access_) }
#define X86_REX2_ALU(name_, base_, access_, lock_) \
    X86_REX2((name_), (base_) + 0, X86_REX2_FORM_RM_REG, \
        X86_REX2_FLAG_BYTE | (lock_), (access_)), \
    X86_REX2((name_), (base_) + 1, X86_REX2_FORM_RM_REG, \
        (lock_), (access_)), \
    X86_REX2((name_), (base_) + 2, X86_REX2_FORM_REG_RM, \
        X86_REX2_FLAG_BYTE, (access_)), \
    X86_REX2((name_), (base_) + 3, X86_REX2_FORM_REG_RM, \
        X86_REX2_FLAG_NONE, (access_))

static const x86_rex2_descriptor x86_rex2_map0[] = {
    X86_REX2_ALU(CDISASM_X86_NAME_ADD, 0x00,
        CDISASM_OPERAND_ACCESS_READ_WRITE, X86_REX2_FLAG_LOCKABLE),
    X86_REX2_ALU(CDISASM_X86_NAME_OR, 0x08,
        CDISASM_OPERAND_ACCESS_READ_WRITE, X86_REX2_FLAG_LOCKABLE),
    X86_REX2_ALU(CDISASM_X86_NAME_ADC, 0x10,
        CDISASM_OPERAND_ACCESS_READ_WRITE, X86_REX2_FLAG_LOCKABLE),
    X86_REX2_ALU(CDISASM_X86_NAME_SBB, 0x18,
        CDISASM_OPERAND_ACCESS_READ_WRITE, X86_REX2_FLAG_LOCKABLE),
    X86_REX2_ALU(CDISASM_X86_NAME_AND, 0x20,
        CDISASM_OPERAND_ACCESS_READ_WRITE, X86_REX2_FLAG_LOCKABLE),
    X86_REX2_ALU(CDISASM_X86_NAME_SUB, 0x28,
        CDISASM_OPERAND_ACCESS_READ_WRITE, X86_REX2_FLAG_LOCKABLE),
    X86_REX2_ALU(CDISASM_X86_NAME_XOR, 0x30,
        CDISASM_OPERAND_ACCESS_READ_WRITE, X86_REX2_FLAG_LOCKABLE),
    X86_REX2_ALU(CDISASM_X86_NAME_CMP, 0x38,
        CDISASM_OPERAND_ACCESS_READ, X86_REX2_FLAG_NONE),
    X86_REX2(CDISASM_X86_NAME_TEST, 0x84, X86_REX2_FORM_RM_REG,
        X86_REX2_FLAG_BYTE, CDISASM_OPERAND_ACCESS_READ),
    X86_REX2(CDISASM_X86_NAME_TEST, 0x85, X86_REX2_FORM_RM_REG,
        X86_REX2_FLAG_NONE, CDISASM_OPERAND_ACCESS_READ),
    X86_REX2(CDISASM_X86_NAME_MOV, 0x88, X86_REX2_FORM_RM_REG,
        X86_REX2_FLAG_BYTE, CDISASM_OPERAND_ACCESS_WRITE),
    X86_REX2(CDISASM_X86_NAME_MOV, 0x89, X86_REX2_FORM_RM_REG,
        X86_REX2_FLAG_NONE, CDISASM_OPERAND_ACCESS_WRITE),
    X86_REX2(CDISASM_X86_NAME_MOV, 0x8a, X86_REX2_FORM_REG_RM,
        X86_REX2_FLAG_BYTE, CDISASM_OPERAND_ACCESS_WRITE),
    X86_REX2(CDISASM_X86_NAME_MOV, 0x8b, X86_REX2_FORM_REG_RM,
        X86_REX2_FLAG_NONE, CDISASM_OPERAND_ACCESS_WRITE)
};

#undef X86_REX2_ALU
#undef X86_REX2

