#define X86_OPCODE_TABLE_LENGTH(table_) (sizeof(table_) / sizeof((table_)[0]))

_Static_assert(X86_OPCODE_TABLE_LENGTH(x86_primary_map) == 256u,
    "x86 primary opcode map must contain 256 descriptors");
_Static_assert(X86_OPCODE_TABLE_LENGTH(x86_0f_map) == 256u,
    "x86 0F opcode map must contain 256 descriptors");
_Static_assert(X86_OPCODE_TABLE_LENGTH(x86_0f38_map) == 256u,
    "x86 0F38 opcode map must contain 256 descriptors");
_Static_assert(X86_OPCODE_TABLE_LENGTH(x86_0f3a_map) == 256u,
    "x86 0F3A opcode map must contain 256 descriptors");
_Static_assert(X86_OPCODE_TABLE_LENGTH(x86_3dnow_map) == 256u,
    "x86 3DNow selector map must contain 256 descriptors");

#undef X86_OPCODE_TABLE_LENGTH
#undef X86_OPCODE_DESCRIPTOR

